function draw({board,width,height,params}) {
  const C=VisualBook.palette, lam=params.lambda;
  const h=[1,-2], w=[2,1], y=1;
  const o=VisualBook.dot(w,h), upstream=o-y;
  const data=h.map(v=>upstream*v), reg=w.map(v=>lam*v);
  const total=data.map((v,i)=>v+reg[i]);
  const left=width<500?72:102, right=width-26;
  const axisY=height-45, x=v=>left+(v+1.5)/5*(right-left);
  const rows=[104,224];
  const fmt=v=>Math.abs(v)<1e-9?'0.00':v.toFixed(2).replace('-', '−');
  const legend=[['loss','损失路径',C.blue],['reg','正则路径',C.orange],['sum','合计',C.ink]];
  legend.forEach((a,i)=>{const px=18+i*(width<500?106:146);board.line('key-'+a[0],px,20,px+18,20,a[2],3);board.text('legend-'+a[0],a[1],px+25,24,{size:13,color:a[2]});});
  board.text('forward','o = 0    ∂L/∂o = −1',18,55,{size:14,color:C.muted});
  board.line('zero',x(0),78,x(0),axisY,C.faint,1.5);
  for(let v=-1;v<=3;v++) {
    board.line('tick-'+v,x(v),axisY,x(v),axisY+5,C.muted,1);
    board.text('tick-label-'+v,String(v).replace('-', '−'),x(v),axisY+21,{size:12,color:C.muted,anchor:'middle'});
  }
  board.line('axis',left,axisY,right,axisY,C.muted,1);
  board.text('axis-label','梯度分量',right,axisY+38,{size:12,color:C.muted,anchor:'end'});
  rows.forEach((yy,i)=>{
    board.text('weight-'+i,'w'+(i===0?'₁':'₂')+' = '+w[i],18,yy+4,{size:14,color:C.ink});
    const f={x,y:v=>yy-v,unitX:(right-left)/5,unitY:1};
    board.vector('data-'+i,f,[0,0],[data[i],0],{color:C.blue});
    const fr={x,y:v=>yy+22-v,unitX:(right-left)/5,unitY:1};
    board.line('join-guide-'+i,x(data[i]),yy,x(data[i]),yy+22,C.faint,1);
    if(reg[i]>0) board.vector('reg-'+i,fr,[data[i],0],[total[i],0],{color:C.orange});
    else board.circle('reg-zero-'+i,x(data[i]),yy+22,3,C.orange);
    board.line('sum-guide-'+i,x(total[i]),yy+22,x(total[i]),yy+47,C.faint,1);
    board.circle('junction-'+i,x(data[i]),yy,3,C.blue);
    const ff={x,y:v=>yy+47-v,unitX:(right-left)/5,unitY:1};
    if(Math.abs(total[i])>1e-9) board.vector('total-'+i,ff,[0,0],[total[i],0],{color:C.ink});
    else board.circle('total-zero-'+i,x(0),yy+47,4,C.ink);
    board.text('data-number-'+i,fmt(data[i]),x(data[i]),yy-14,{size:13,color:C.blue,anchor:'middle'});
    board.text('reg-number-'+i,(reg[i]>0?'+':'')+fmt(reg[i]),(x(data[i])+x(total[i]))/2,yy+37,{size:12,color:C.orange,anchor:'middle'});
    board.text('sum-number-'+i,fmt(total[i]),x(total[i]),yy+68,{size:14,color:C.ink,anchor:'middle',weight:600});
  });
  return {input:{h,w,y,lambda:lam},output:o,upstream,dataGradient:data,regularizationGradient:reg,totalGradient:total};
}

function draw({board,width,height,progress}) {
  const C=VisualBook.palette, p=VisualBook.clamp(progress,0,1);
  const left=54, right=width-24, x=t=>left+t*(right-left);
  const births=[0,0.15,0.30], reads=[0.90,0.75,0.60];
  const rows=[104,173,242], labels=['a₀','a₁','a₂'];
  const saved=births.map((b,i)=>p>=b && p<reads[i]);
  const count=saved.filter(Boolean).length;
  board.text('phase',p<0.45?'前向：生成中间值':p<0.5?'计算损失':p<0.9?'反向：读取中间值':'本轮反传完成',18,24,{size:15,color:C.ink});
  board.text('count','保留 '+count+' / 3',width-18,24,{size:13,color:C.blue,anchor:'end'});
  [['interval','区间',C.faint],['retained','保留',C.blue],['read','读取',C.orange]].forEach((a,i)=>{const lx=18+i*(width<500?98:130);board.line('key-'+a[0],lx,49,lx+18,49,a[2],4);board.text('legend-'+a[0],a[1],lx+25,53,{size:12,color:C.muted});});
  board.text('forward','前向',x(0.22),75,{size:13,color:C.muted,anchor:'middle'});
  board.text('backward','反向',x(0.74),75,{size:13,color:C.muted,anchor:'middle'});
  board.line('split',x(.5),85,x(.5),272,C.faint,1);
  rows.forEach((yy,i)=>{
    board.text('name-'+i,labels[i],18,yy+13,{size:16,color:C.ink});
    board.rect('lifetime-'+i,x(births[i]),yy,x(reads[i])-x(births[i]),16,C.faint,{rx:3});
    const end=Math.min(p,reads[i]);
    if(saved[i] && end>births[i]) board.rect('saved-'+i,x(births[i]),yy,x(end)-x(births[i]),16,C.blue,{rx:3});
    if(saved[i]) board.circle('live-start-'+i,x(births[i]),yy+8,3,C.blue);
    board.line('born-'+i,x(births[i]),yy-3,x(births[i]),yy+19,C.muted,1);
    board.circle('read-'+i,x(reads[i]),yy+8,4,C.orange);
    const active=Math.max(0,1-Math.abs(p-reads[i])/0.035);
    if(active>0) board.circle('reading-'+i,x(reads[i]),yy+8,4+7*active,C.orange);
    const status=p<births[i]?'尚未生成':saved[i]?'等待反传读取':'已读取，可释放';
    board.text('status-'+i,status,right,yy+38,{size:12,color:saved[i]?C.blue:C.muted,anchor:'end'});
  });
  [[87,125],[150,194],[219,272]].forEach((span,i)=>board.line('cursor-'+i,x(p),span[0],x(p),span[1],C.ink,1.5,.8));
  board.circle('cursor-head',x(p),87,3,C.ink);
  const ay=height-63;
  board.line('axis',left,ay,right,ay,C.muted,1);
  [[0,'开始'],[.5,'损失'],[1,'完成']].forEach((a,i)=>{board.line('tick-'+i,x(a[0]),ay,x(a[0]),ay+5,C.muted,1);board.text('tick-label-'+i,a[1],x(a[0]),ay+22,{size:12,color:C.muted,anchor:i===0?'start':i===2?'end':'middle'});});
  board.text('axis-caption','计算顺序（不是用时）',right,ay+43,{size:12,color:C.muted,anchor:'end'});
  return {progress:p,activationIds:labels,births,lastBackwardReads:reads,saved,savedActivationCount:count,schedule:'示意三层线性链；每个值最后一次读取后允许释放；不表示框架的实际内存分配或硬件时间'};
}
